  $dir='C:\LabEx\Labs\'+$labId
  foreach($p in @('C:\LabEx','C:\LabEx\Labs',$dir)){
    if((Test-Path -LiteralPath $p) -and ((Get-Item -LiteralPath $p -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Reparse workspace refused'}
